   303→      if (now - lastProgressCommitRef.current < PROGRESS_THROTTLE_MS) return;
   304→      lastProgressCommitRef.current = now;
   305→
   306→      setGlobalAudioPlayerProgress(e.currentPosition, durationRef.current || undefined);
