   318→        widget.unbind(events.READY);
   319→        widget.unbind(events.PLAY);
   320→        widget.unbind(events.PAUSE);
   321→        widget.unbind(events.FINISH);
   322→        widget.unbind(events.PLAY_PROGRESS);
   323→        widget.unbind(events.ERROR);
   324→        widget.pause();
