    97→            <rect
    98→              key={`bg-${i}`}
    99→              x={i + 0.15}
   100→              y={y}
   101→              width={0.7}
   102→              height={h}
   103→              rx={0.2}
   104→              fill="currentColor"
   105→              opacity={disabled ? 0.15 : 0.25}
   106→              className="text-neo-text"
   107→            />
   108→          );
   109→        })}
   110→
   111→        {/* Progress bars */}
