     5→type WaveformSource = "soundcloud" | "fallback" | "none";
     6→
     7→type UseSoundCloudWaveformResult = {
     8→  samples: number[] | null;
     9→  source: WaveformSource;
    10→  isLoading: boolean;
    11→};
    12→
    13→const waveformCache = new Map<string, number[]>();
    14→
    15→const hashString = (value: string) => {
    16→  let hash = 0;
    17→  for (let i = 0; i < value.length; i += 1) {
    18→    hash = (hash << 5) - hash + value.charCodeAt(i);
    19→    hash |= 0;
    20→  }
    21→  return hash >>> 0;
    22→};
    23→
    24→const mulberry32 = (seed: number) => {
    25→  let a = seed;
    26→  return () => {
    27→    a |= 0;
    28→    a = (a + 0x6d2b79f5) | 0;
    29→    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    30→    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    31→    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    32→  };
    33→};
    34→
    35→const generateFallbackWaveform = (seed: number, barsCount: number) => {
    36→  const rnd = mulberry32(seed);
    37→  const values = Array.from({ length: barsCount }, () => rnd());
    38→
    39→  // Smooth it a bit so it looks like an actual waveform.
    40→  const smoothed = values.map((v, i) => {
    41→    const prev = values[i - 1] ?? v;
    42→    const next = values[i + 1] ?? v;
    43→    return (prev + v * 2 + next) / 4;
    44→  });
    45→
    46→  // Boost contrast and clamp.
    47→  return smoothed.map((v) => Math.max(0.08, Math.min(1, v * 1.2)));
    48→};
    49→
    50→const resampleMax = (input: number[], barsCount: number) => {
    51→  if (input.length === 0) return Array.from({ length: barsCount }, () => 0);
    52→  if (input.length <= barsCount) {
    53→    const max = Math.max(...input, 1);
    54→    const normalized = input.map((v) => (max ? v / max : 0));
    55→    return [...normalized, ...Array.from({ length: barsCount - input.length }, () => 0)];
    56→  }
    57→
    58→  const size = input.length / barsCount;
    59→  const buckets: number[] = [];
    60→  for (let i = 0; i < barsCount; i += 1) {
    61→    const start = Math.floor(i * size);
    62→    const end = Math.floor((i + 1) * size);
    63→    let maxInBucket = 0;
    64→    for (let j = start; j < end; j += 1) {
    65→      maxInBucket = Math.max(maxInBucket, input[j] ?? 0);
    66→    }
    67→    buckets.push(maxInBucket);
    68→  }
    69→
    70→  const max = Math.max(...buckets, 1);
    71→  return buckets.map((v) => (max ? v / max : 0));
    72→};
    73→
    74→export function useSoundCloudWaveform(
    75→  waveformUrl: string | null | undefined,
    76→  soundId: number | null | undefined,
    77→  barsCount = 96
    78→): UseSoundCloudWaveformResult {
    79→  const [samples, setSamples] = useState<number[] | null>(null);
    80→  const [source, setSource] = useState<WaveformSource>("none");
    81→  const [isLoading, setIsLoading] = useState(false);
    82→
    83→  const fallbackSeed = useMemo(() => {
    84→    if (typeof soundId === "number") return soundId;
    85→    if (waveformUrl) return hashString(waveformUrl);
    86→    return 1337;
    87→  }, [soundId, waveformUrl]);
    88→
    89→  useEffect(() => {
    90→    const fallback = () => {
    91→      setSamples(generateFallbackWaveform(fallbackSeed, barsCount));
    92→      setSource(waveformUrl ? "fallback" : "none");
    93→      setIsLoading(false);
    94→    };
    95→
    96→    if (!waveformUrl) {
    97→      fallback();
    98→      return;
    99→    }
   100→
   101→    const cached = waveformCache.get(waveformUrl);
   102→    if (cached) {
   103→      setSamples(cached);
   104→      setSource("soundcloud");
   105→      setIsLoading(false);
   106→      return;
   107→    }
   108→
   109→    const controller = new AbortController();
   110→    setIsLoading(true);
   111→
   112→    fetch(waveformUrl, { signal: controller.signal })
   113→      .then((res) => {
   114→        if (!res.ok) throw new Error(`Waveform fetch failed: ${res.status}`);
   115→        return res.json() as Promise<{ samples?: number[] }>;
   116→      })
   117→      .then((data) => {
   118→        const rawSamples = Array.isArray(data.samples) ? data.samples : null;
   119→        if (!rawSamples) {
   120→          fallback();
   121→          return;
   122→        }
   123→        const normalized = resampleMax(rawSamples, barsCount);
   124→        waveformCache.set(waveformUrl, normalized);
   125→        setSamples(normalized);
   126→        setSource("soundcloud");
   127→        setIsLoading(false);
   128→      })
   129→      .catch((err) => {
   130→        if (err?.name === "AbortError") return;
   131→        fallback();
   132→      });
   133→
   134→    return () => controller.abort();
   135→  }, [barsCount, fallbackSeed, waveformUrl]);
   136→
   137→  return { samples, source, isLoading };
   138→}
