    75→export const GlobalAudioPlayerEngine = () => {
    76→  const { state: consentState } = useConsent();
    77→  const mediaAllowed = consentState.media;
    78→
    79→  const iframeRef = useRef<HTMLIFrameElement | null>(null);
    80→  const widgetRef = useRef<SoundCloudWidget | null>(null);
    81→  const soundIdRef = useRef<number | null>(null);
    82→  const readyTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
    83→  const lastProgressCommitRef = useRef(0);
    84→  const durationRef = useRef(0);
    85→
    86→  const [scriptStatus, setScriptStatus] = useState<"idle" | "loaded" | "error">("idle");
    87→
    88→  useEffect(() => {
    89→    hydrateGlobalAudioPlayerVolume();
    90→  }, []);
    91→
    92→  // Fetch tracks from API as soon as media is allowed (don't wait for widget)
    93→  useEffect(() => {
    94→    if (!mediaAllowed) return;
    95→    // Fetch tracks immediately when consent is given
    96→    fetchFullSoundCloudQueue().catch(() => {
    97→      // Silently fail - widget will provide fallback queue
    98→    });
    99→  }, [mediaAllowed]);
   100→
   101→  useEffect(() => {
   102→    if (!mediaAllowed) return;
   103→    if (scriptStatus !== "idle") return;
   104→    if (window.SC?.Widget) setScriptStatus("loaded");
   105→  }, [mediaAllowed, scriptStatus]);
   106→
   107→  useEffect(() => {
   108→    setGlobalAudioPlayerMediaAllowed(mediaAllowed);
   109→
   110→    if (!mediaAllowed) {
   111→      try {
   112→        widgetRef.current?.pause();
   113→      } catch {
   114→        // noop
   115→      }
   116→      widgetRef.current = null;
   117→      setGlobalAudioPlayerWidget(null);
   118→      setGlobalAudioPlayerStatus("idle");
   119→      setGlobalAudioPlayerPlaying(false);
   120→      setGlobalAudioPlayerError(null);
   121→      resetFullQueueFetchState();
   122→      durationRef.current = 0;
   123→      soundIdRef.current = null;
   124→      setScriptStatus("idle");
   125→      if (readyTimeoutRef.current) clearTimeout(readyTimeoutRef.current);
   126→      readyTimeoutRef.current = null;
   127→    }
   128→  }, [mediaAllowed]);
   129→
   130→  const canInitWidget = useMemo(() => {
   131→    return mediaAllowed && scriptStatus === "loaded" && !!iframeRef.current && !widgetRef.current;
   132→  }, [mediaAllowed, scriptStatus]);
   133→
   134→  useEffect(() => {
   135→    if (!canInitWidget) return;
   136→    const iframeEl = iframeRef.current;
   137→    if (!iframeEl) return;
   138→
   139→    const scWidgetFactory = window.SC?.Widget;
   140→    if (!scWidgetFactory) {
   141→      setGlobalAudioPlayerStatus("error");
   142→      setGlobalAudioPlayerError("SoundCloud API unavailable");
   143→      return;
   144→    }
   145→    const events = scWidgetFactory.Events;
   146→    if (!events) {
   147→      setGlobalAudioPlayerStatus("error");
   148→      setGlobalAudioPlayerError("SoundCloud events unavailable");
   149→      return;
   150→    }
   151→
   152→    const widget = scWidgetFactory(iframeEl);
   153→    widgetRef.current = widget;
   154→    setGlobalAudioPlayerWidget(widget);
   155→    setGlobalAudioPlayerStatus("loading");
   156→    setGlobalAudioPlayerError(null);
   157→
   158→    const clearReadyTimeout = () => {
   159→      if (readyTimeoutRef.current) clearTimeout(readyTimeoutRef.current);
   160→      readyTimeoutRef.current = null;
   161→    };
   162→
   163→    readyTimeoutRef.current = setTimeout(() => {
   164→      setGlobalAudioPlayerStatus("error");
   165→      setGlobalAudioPlayerError("SoundCloud player timed out");
   166→    }, READY_TIMEOUT_MS);
   167→
   168→    const refreshSound = () => {
   169→      try {
   170→        widget.getCurrentSound((sound: SoundCloudSound) => {
   171→          const track = mapSound(sound);
   172→          if (track) {
   173→            setGlobalAudioPlayerTrack(track);
   174→            const { queue, currentIndex } = getGlobalAudioPlayerState();
   175→            if (queue.length) {
   176→              const idx = queue.findIndex((t) => t.id === track.id);
   177→              if (idx >= 0 && idx !== currentIndex) setGlobalAudioPlayerCurrentIndex(idx);
   178→            }
   179→            if (soundIdRef.current !== track.id) {
   180→              soundIdRef.current = track.id;
