   227→            setGlobalAudioPlayerTrack(queue[0]);
   228→            setGlobalAudioPlayerCurrentIndex(0);
   229→          } else {
   230→            try {
   231→              widget.getCurrentSoundIndex((idx: number) => {
   232→                if (!Number.isFinite(idx)) return;
