   253→      } catch {
   254→        // noop
   255→      }
   256→
   257→      // Skip to first track to force loading metadata (without playing)
   258→      try {
   259→        widget.skip(0);
   260→      } catch {
   261→        // noop
   262→      }
   263→
   264→      refreshQueue();
   265→      refreshSound();
   266→      tryConsumePendingGlobalAudioPlayerAction();
   267→
   268→      // Retry loading queue after a delay if it's still empty
   269→      // (widget may need time to load metadata after READY)
