   290→    widget.bind(events.PAUSE, () => {
   291→      setGlobalAudioPlayerPlaying(false);
   292→    });
   293→
   294→    widget.bind(events.FINISH, () => {
   295→      setGlobalAudioPlayerPlaying(false);
   296→      setGlobalAudioPlayerProgress(0, durationRef.current || undefined);
