   195→        // noop
   196→      }
   197→    };
   198→
   199→    const refreshQueue = () => {
   200→      try {
   201→        widget.getSounds((sounds: SoundCloudSound[]) => {
   202→          if (!Array.isArray(sounds) || sounds.length === 0) return;
   203→          const queue = sounds
