   205→              const track = mapSound(sound);
   206→              if (!track) return null;
   207→              return {
   208→                track,
   209→                widgetIndex,
   210→                sortMs: getSoundSortDateMs(sound) ?? 0,
   211→              };
   212→            })
   213→            .filter((item): item is NonNullable<typeof item> => !!item)
   214→            .sort((a, b) => {
   215→              const dateDiff = b.sortMs - a.sortMs;
   216→              if (dateDiff) return dateDiff;
