   221→          const currentId = getGlobalAudioPlayerState().track?.id;
   222→          if (typeof currentId === "number") {
   223→            const idx = queue.findIndex((t) => t.id === currentId);
   224→            if (idx >= 0) setGlobalAudioPlayerCurrentIndex(idx);
   225→          } else if (queue.length > 0) {
   226→            // No track selected yet, set the first track from the queue
   227→            setGlobalAudioPlayerTrack(queue[0]);
   228→            setGlobalAudioPlayerCurrentIndex(0);
   229→          } else {
   230→            try {
   231→              widget.getCurrentSoundIndex((idx: number) => {
   232→                if (!Number.isFinite(idx)) return;
   233→                const safeWidgetIndex = Math.max(0, Math.floor(idx));
   234→                const queueIndex = queue.findIndex((t) => t.widgetIndex === safeWidgetIndex);
   235→                if (queueIndex >= 0) setGlobalAudioPlayerCurrentIndex(queueIndex);
   236→              });
   237→            } catch {
   238→              // noop
   239→            }
   240→          }
   241→        });
   242→      } catch {
   243→        // noop
   244→      }
   245→    };
   246→
   247→    widget.bind(events.READY, () => {
   248→      clearReadyTimeout();
   249→      setGlobalAudioPlayerStatus("ready");
   250→      setGlobalAudioPlayerError(null);
   251→      try {
   252→        widget.setVolume(getGlobalAudioPlayerState().volume);
   253→      } catch {
   254→        // noop
   255→      }
   256→
   257→      // Skip to first track to force loading metadata (without playing)
   258→      try {
   259→        widget.skip(0);
   260→      } catch {
   261→        // noop
   262→      }
   263→
   264→      refreshQueue();
   265→      refreshSound();
   266→      tryConsumePendingGlobalAudioPlayerAction();
   267→
   268→      // Retry loading queue after a delay if it's still empty
   269→      // (widget may need time to load metadata after READY)
   270→      setTimeout(() => {
   271→        const state = getGlobalAudioPlayerState();
   272→        if (state.queue.length === 0 || !state.track) {
   273→          refreshQueue();
   274→          refreshSound();
   275→        }
   276→      }, 1000);
   277→
   278→      // Fetch full track list from API (widget only provides first 20)
   279→      fetchFullSoundCloudQueue().catch(() => {
   280→        // Silently fall back to widget queue
   281→      });
   282→    });
   283→
   284→    widget.bind(events.PLAY, () => {
   285→      setGlobalAudioPlayerPlaying(true);
   286→      if (getGlobalAudioPlayerState().queue.length === 0) refreshQueue();
   287→      refreshSound();
   288→    });
   289→
   290→    widget.bind(events.PAUSE, () => {
   291→      setGlobalAudioPlayerPlaying(false);
   292→    });
   293→
   294→    widget.bind(events.FINISH, () => {
   295→      setGlobalAudioPlayerPlaying(false);
   296→      setGlobalAudioPlayerProgress(0, durationRef.current || undefined);
   297→      refreshSound();
   298→    });
   299→
   300→    widget.bind(events.PLAY_PROGRESS, (e?: SoundCloudPlayProgressEvent) => {
   301→      if (!e) return;
   302→      const now = Date.now();
   303→      if (now - lastProgressCommitRef.current < PROGRESS_THROTTLE_MS) return;
   304→      lastProgressCommitRef.current = now;
   305→
   306→      setGlobalAudioPlayerProgress(e.currentPosition, durationRef.current || undefined);
   307→    });
   308→
   309→    widget.bind(events.ERROR, () => {
   310→      clearReadyTimeout();
   311→      setGlobalAudioPlayerStatus("error");
   312→      setGlobalAudioPlayerError("SoundCloud player error");
   313→    });
   314→
   315→    return () => {
   316→      clearReadyTimeout();
   317→      try {
   318→        widget.unbind(events.READY);
   319→        widget.unbind(events.PLAY);
   320→        widget.unbind(events.PAUSE);
   321→        widget.unbind(events.FINISH);
   322→        widget.unbind(events.PLAY_PROGRESS);
   323→        widget.unbind(events.ERROR);
   324→        widget.pause();
   325→      } catch {
   326→        // noop
   327→      }
   328→      widgetRef.current = null;
   329→      setGlobalAudioPlayerWidget(null);
   330→      durationRef.current = 0;
   331→      soundIdRef.current = null;
   332→      setGlobalAudioPlayerStatus("idle");
   333→      setGlobalAudioPlayerPlaying(false);
   334→    };
   335→  }, [canInitWidget]);
   336→
   337→  if (!mediaAllowed) return null;
   338→
   339→  return (
   340→    <>
   341→      <Script
   342→        src="https://w.soundcloud.com/player/api.js"
   343→        strategy="afterInteractive"
   344→        onReady={() => setScriptStatus("loaded")}
   345→        onLoad={() => setScriptStatus("loaded")}
