    65→    id: sound.id,
    66→    title: sound.title,
    67→    artist: sound.user?.username,
    68→    artworkUrl: sound.artwork_url ?? null,
    69→    waveformUrl: sound.waveform_url ?? null,
    70→    permalinkUrl: sound.permalink_url ?? null,
    71→    durationMs: typeof sound.duration === "number" ? sound.duration : undefined,
    72→  };
    73→};
