   300→  if (action.type === "select") {
   301→    try {
   302→      widget.skip(action.widgetIndex);
   303→      widget.play();
   304→      return true;
   305→    } catch {
   306→      return false;
   307→    }
   308→  }
   309→
   310→  if (action.type === "play") {
   311→    widget.play();
   312→    return true;
   313→  }
   314→  if (action.type === "toggle") {
   315→    widget.toggle();
   316→    return true;
   317→  }
   318→  return false;
   319→};
