    54→    parseSoundCloudDateMs(sound.release_date) ??
    55→    parseSoundCloudDateMs(sound.display_date) ??
    56→    parseSoundCloudDateMs(sound.created_at) ??
    57→    parseSoundCloudDateMs(sound.last_modified) ??
    58→    null
    59→  );
    60→};
