     3→const SOUNDCLOUD_PROFILE_URL = "https://soundcloud.com/loic-ghanem";
     4→const CACHE_TTL_SECONDS = 3600; // 1 hour
     5→
     6→type SoundCloudTrack = {
     7→  id: number;
     8→  title: string;
     9→  permalink_url: string;
    10→  artwork_url: string | null;
    11→  waveform_url: string | null;
    12→  duration: number;
    13→  created_at: string;
    14→  display_date?: string;
    15→  release_date?: string;
    16→  user: {
    17→    username: string;
    18→    avatar_url?: string;
    19→  };
    20→};
    21→
    22→type SoundCloudTracksResponse = {
    23→  collection: SoundCloudTrack[];
    24→  next_href?: string;
    25→};
    26→
    27→type SoundCloudUser = {
    28→  id: number;
    29→  username: string;
    30→  track_count: number;
    31→};
