   111→
   112→  while (hasMore) {
   113→    const url = `https://api-v2.soundcloud.com/users/${userId}/tracks?client_id=${clientId}&limit=${limit}&offset=${offset}&linked_partitioning=1`;
   114→    const res = await fetch(url);
   115→
   116→    if (!res.ok) break;
   117→
   118→    const data: SoundCloudTracksResponse = await res.json();
   119→    if (data.collection && data.collection.length > 0) {
   120→      allTracks.push(...data.collection);
   121→      offset += data.collection.length;
   122→      hasMore = !!data.next_href && data.collection.length === limit;
   123→    } else {
   124→      hasMore = false;
   125→    }
   126→
   127→    // Safety limit
   128→    if (allTracks.length > 1000) break;
   129→  }
   130→
   131→  return allTracks;
   132→}
   133→
   134→function mapTrack(track: SoundCloudTrack) {
   135→  return {
   136→    id: track.id,
   137→    title: track.title,
   138→    artist: track.user?.username ?? "Unknown",
   139→    artworkUrl: track.artwork_url,
   140→    waveformUrl: track.waveform_url,
   141→    permalinkUrl: track.permalink_url,
   142→    durationMs: track.duration,
   143→    createdAt: track.created_at,
   144→    displayDate: track.display_date,
   145→    releaseDate: track.release_date,
   146→  };
   147→}
   148→
   149→export async function GET() {
   150→  try {
   151→    const clientId = await getClientId();
   152→    if (!clientId) {
   153→      return NextResponse.json(
   154→        { error: "Unable to retrieve SoundCloud client ID" },
   155→        { status: 503 }
   156→      );
   157→    }
   158→
   159→    const user = await resolveUser(clientId);
   160→    if (!user) {
   161→      return NextResponse.json({ error: "Unable to resolve SoundCloud user" }, { status: 404 });
   162→    }
   163→
   164→    const tracks = await fetchAllTracks(user.id, clientId);
   165→
   166→    // Sort by date (most recent first)
   167→    const sortedTracks = tracks.sort((a, b) => {
   168→      const dateA = new Date(a.release_date || a.display_date || a.created_at).getTime();
   169→      const dateB = new Date(b.release_date || b.display_date || b.created_at).getTime();
   170→      return dateB - dateA;
   171→    });
   172→
   173→    const mappedTracks = sortedTracks.map(mapTrack);
   174→
   175→    return NextResponse.json(
   176→      {
   177→        tracks: mappedTracks,
   178→        total: mappedTracks.length,
   179→        user: {
   180→          id: user.id,
   181→          username: user.username,
   182→          trackCount: user.track_count,
   183→        },
   184→      },
   185→      {
   186→        headers: {
   187→          "Cache-Control": `public, s-maxage=${CACHE_TTL_SECONDS}, stale-while-revalidate=86400`,
   188→        },
   189→      }
   190→    );
   191→  } catch (error) {
   192→    // eslint-disable-next-line no-console
   193→    console.error("SoundCloud API error:", error);
   194→    return NextResponse.json({ error: "Failed to fetch SoundCloud tracks" }, { status: 500 });
   195→  }
   196→}
