"use client";

import React, { useEffect, useMemo, useRef, useState } from "react";
import { AnimatePresence, motion } from "framer-motion";
import {
  ChevronDown,
  ChevronUp,
  ExternalLink,
  Pause,
  Play,
  SkipBack,
  SkipForward,
  Volume2,
  VolumeX,
  X,
} from "lucide-react";
import Image from "next/image";
import { useTranslations } from "next-intl";
import { usePathname } from "next/navigation";
import { useConsent } from "../legal/ConsentProvider";
import { useSoundCloudWaveform } from "@/lib/hooks/useSoundCloudWaveform";
import { SOUND_CLOUD_PROFILE_URL, useGlobalAudioPlayer } from "@/lib/player/globalAudioPlayer";
import { cn } from "@/lib/utils";
import { SoundCloudIcon } from "./SoundCloudIcon";
import { SoundCloudTrackList } from "./SoundCloudTrackList";
import { SoundCloudWaveform } from "./SoundCloudWaveform";
import { formatTime } from "./utils";

const isHomePathname = (pathname: string | null) => {
  const path = pathname ?? "";
  return /^\/(en|fr)$/.test(path);
};

const normalizeArtworkUrl = (url: string | null | undefined, size: "t200x200" | "t500x500") => {
  if (!url) return null;
  return url.replace("-large", `-${size}`);
};

export const GlobalAudioPlayerBar = () => {
  const t = useTranslations("musicPlayer");
  const pathname = usePathname();
  const isHome = isHomePathname(pathname);

  const { openManager } = useConsent();
  const {
    status,
    mediaAllowed,
    hasStarted,
    isDismissed,
    isPlaying,
    track,
    queue,
    currentIndex,
    positionMs,
    durationMs,
    volume,
    error,
    actions,
  } = useGlobalAudioPlayer();

  const [isCollapsed, setIsCollapsed] = useState(true);
  const [lastNonZeroVolume, setLastNonZeroVolume] = useState(80);

  const [showOnHome, setShowOnHome] = useState(false);

  useEffect(() => {
    if (!isHome) {
      setShowOnHome(true);
      return;
    }

    const heroSelector = '[data-hero-audio-player="true"]';
    const showThreshold = 0.15;

    let raf = 0;
    let rafScroll = 0;
    let observer: IntersectionObserver | null = null;
    let detachScrollFallback: (() => void) | null = null;

    const installScrollFallback = () => {
      const update = () => {
        const threshold = Math.max(520, Math.floor(window.innerHeight * 0.9));
        setShowOnHome(window.scrollY > threshold);
      };

      const onScroll = () => {
        if (rafScroll) return;
        rafScroll = window.requestAnimationFrame(() => {
          rafScroll = 0;
          update();
        });
      };

      update();
      window.addEventListener("scroll", onScroll, { passive: true });
      window.addEventListener("resize", onScroll, { passive: true });
      detachScrollFallback = () => {
        window.removeEventListener("scroll", onScroll);
        window.removeEventListener("resize", onScroll);
        if (rafScroll) window.cancelAnimationFrame(rafScroll);
      };
    };

    const attachObserver = () => {
      const heroEl = document.querySelector(heroSelector);
      if (!heroEl) {
        raf = window.requestAnimationFrame(attachObserver);
        return;
      }

      if (typeof IntersectionObserver === "undefined") {
        installScrollFallback();
        return;
      }

      observer = new IntersectionObserver(
        (entries) => {
          const entry = entries[0];
          if (!entry) return;
          setShowOnHome(!entry.isIntersecting || entry.intersectionRatio < showThreshold);
        },
        { threshold: [0, 0.05, showThreshold, 0.25, 0.5, 0.75, 1] }
      );

      observer.observe(heroEl);
    };

    attachObserver();

    return () => {
      if (raf) window.cancelAnimationFrame(raf);
      detachScrollFallback?.();
      observer?.disconnect();
    };
  }, [isHome]);

  useEffect(() => {
    if (volume > 0) setLastNonZeroVolume(volume);
  }, [volume]);

  const shouldShowBar = hasStarted && !isDismissed && (!isHome || showOnHome);
  const shouldShowReopen = hasStarted && isDismissed;

  const progress = durationMs > 0 ? Math.min(1, positionMs / durationMs) : 0;
  const remainingMs = Math.max(0, durationMs - positionMs);
  const externalUrl = track?.permalinkUrl || SOUND_CLOUD_PROFILE_URL;
  const artworkUrl = normalizeArtworkUrl(track?.artworkUrl ?? null, "t200x200");

  const { samples, isLoading: isWaveformLoading } = useSoundCloudWaveform(
    mediaAllowed ? track?.waveformUrl : null,
    track?.id,
    96
  );

  const displayTitle = track?.title || t("status.noTrack");
  const displayArtist = track?.artist || t("status.soundcloud");

  const isPlayerUnavailable = status === "error" || !!error;
  const controlsDisabled = !mediaAllowed || status !== "ready" || isPlayerUnavailable;

  const statusLabel = useMemo(() => {
    if (!mediaAllowed) return t("status.mediaDisabled");
    if (isPlayerUnavailable) return t("status.unavailable");
    if (status === "loading") return t("status.loading");
    return isPlaying ? t("status.playing") : t("status.paused");
  }, [isPlayerUnavailable, isPlaying, mediaAllowed, status, t]);

  const bottomOffsetPx = 12;
  const pageGapPx = 12;
  const barMeasureRef = useRef<HTMLDivElement | null>(null);
  const [measuredHeightPx, setMeasuredHeightPx] = useState(0);

  useEffect(() => {
    if (!shouldShowBar) {
      setMeasuredHeightPx(0);
      return;
    }

    const el = barMeasureRef.current;
    if (!el) return;

    const update = () => setMeasuredHeightPx(Math.ceil(el.getBoundingClientRect().height));
    update();

    if (typeof ResizeObserver === "undefined") {
      window.addEventListener("resize", update);
      return () => window.removeEventListener("resize", update);
    }

    const ro = new ResizeObserver(() => update());
    ro.observe(el);
    return () => ro.disconnect();
  }, [shouldShowBar]);

  const fallbackHeightPx = isCollapsed ? 96 : 320;
  const spacerHeightPx = (measuredHeightPx || fallbackHeightPx) + bottomOffsetPx + pageGapPx;

  return (
    <>
      {shouldShowBar && (
        <div
          aria-hidden="true"
          style={{ height: `calc(${spacerHeightPx}px + env(safe-area-inset-bottom))` }}
        />
      )}

      <AnimatePresence>
        {shouldShowBar && (
          <motion.div
            initial={{ y: 120, opacity: 0 }}
            animate={{ y: 0, opacity: 1 }}
            exit={{ y: 120, opacity: 0 }}
            transition={{ duration: 0.35, ease: [0.25, 0.4, 0.25, 1] }}
            className="fixed inset-x-0 z-40 px-3 md:px-6"
            style={{ bottom: `calc(${bottomOffsetPx}px + env(safe-area-inset-bottom))` }}
          >
            <div className="mx-auto max-w-6xl">
              <div className="relative">
                <div className="absolute -top-2 -left-2 w-full h-full border-4 border-neo-border bg-neo-bg -z-10" />

                <div
                  ref={barMeasureRef}
                  className="border-4 border-neo-border bg-neo-surface shadow-[10px_10px_0px_0px_var(--neo-accent)] overflow-hidden"
                >
                  <div className="flex flex-col sm:flex-row sm:items-center gap-3 md:gap-4 p-3 md:p-4">
                    {/* Track info */}
                    <div className="flex items-center gap-3 min-w-0 flex-1 w-full">
                      <div className="h-11 w-11 md:h-12 md:w-12 border-2 border-neo-border bg-neo-surface shadow-[3px_3px_0px_0px_var(--neo-shadow)] overflow-hidden flex-shrink-0">
                        {artworkUrl ? (
                          <Image
                            src={artworkUrl}
                            alt=""
                            width={48}
                            height={48}
                            className="h-full w-full object-cover"
                            draggable={false}
                            referrerPolicy="no-referrer"
                          />
                        ) : (
                          <div className="h-full w-full flex items-center justify-center bg-neo-text text-neo-text-inverse">
                            <SoundCloudIcon className="w-5 h-5" />
                          </div>
                        )}
                      </div>
                      <div className="min-w-0">
                        <div className="font-mono text-[10px] uppercase tracking-[0.2em] text-neo-accent">
                          {statusLabel}
                        </div>
                        <div className="font-black uppercase tracking-tight text-neo-text line-clamp-2 sm:line-clamp-1">
                          {displayTitle}
                        </div>
                        <div className="font-mono text-xs text-neo-text/60 line-clamp-1">
                          {displayArtist}
                        </div>
                      </div>
                    </div>

                    {/* Controls */}
                    <div className="flex items-center gap-2 md:gap-3 flex-shrink-0 w-full sm:w-auto flex-wrap sm:flex-nowrap justify-between sm:justify-start">
                      <button
                        type="button"
                        onClick={() => actions.previous()}
                        disabled={controlsDisabled}
                        aria-label={t("controls.previous")}
                        className={cn(
                          "h-9 w-9 sm:h-10 sm:w-10 border-2 border-neo-border bg-neo-bg text-neo-text shadow-[3px_3px_0px_0px_var(--neo-shadow)]",
                          "hover:-translate-y-0.5 transition-transform",
                          "disabled:opacity-40 disabled:hover:translate-y-0 disabled:cursor-not-allowed"
                        )}
                      >
                        <SkipBack className="w-5 h-5 mx-auto" />
                      </button>

                      <button
                        type="button"
                        onClick={() => {
                          if (!mediaAllowed) {
                            openManager();
                            return;
                          }
                          actions.toggle();
                        }}
                        aria-label={isPlaying ? t("controls.pause") : t("controls.play")}
                        className={cn(
                          "h-11 w-11 sm:h-12 sm:w-12 border-3 border-neo-border bg-neo-accent text-neo-text-inverse",
                          "shadow-[4px_4px_0px_0px_var(--neo-border)] hover:-translate-y-0.5 transition-transform",
                          !mediaAllowed && "bg-neo-text text-neo-text-inverse"
                        )}
                      >
                        {isPlaying ? (
                          <Pause className="w-6 h-6 mx-auto" />
                        ) : (
                          <Play className="w-6 h-6 mx-auto translate-x-[1px]" />
                        )}
                      </button>

                      <button
                        type="button"
                        onClick={() => actions.next()}
                        disabled={controlsDisabled}
                        aria-label={t("controls.next")}
                        className={cn(
                          "h-9 w-9 sm:h-10 sm:w-10 border-2 border-neo-border bg-neo-bg text-neo-text shadow-[3px_3px_0px_0px_var(--neo-shadow)]",
                          "hover:-translate-y-0.5 transition-transform",
                          "disabled:opacity-40 disabled:hover:translate-y-0 disabled:cursor-not-allowed"
                        )}
                      >
                        <SkipForward className="w-5 h-5 mx-auto" />
                      </button>

                      {/* Volume */}
                      <button
                        type="button"
                        onClick={() => {
                          if (!mediaAllowed) {
                            openManager();
                            return;
                          }
                          actions.setVolume(volume === 0 ? lastNonZeroVolume : 0);
                        }}
                        disabled={!mediaAllowed}
                        aria-label={volume === 0 ? t("controls.unmute") : t("controls.mute")}
                        className={cn(
                          "md:hidden h-9 w-9 sm:h-10 sm:w-10 border-2 border-neo-border bg-neo-bg text-neo-text shadow-[3px_3px_0px_0px_var(--neo-shadow)]",
                          "hover:-translate-y-0.5 transition-transform",
                          "disabled:opacity-40 disabled:hover:translate-y-0 disabled:cursor-not-allowed"
                        )}
                      >
                        {volume === 0 ? (
                          <VolumeX className="w-5 h-5 mx-auto" />
                        ) : (
                          <Volume2 className="w-5 h-5 mx-auto" />
                        )}
                      </button>

                      <div className="hidden md:flex items-center gap-2 border-2 border-neo-border bg-neo-bg shadow-[3px_3px_0px_0px_var(--neo-shadow)] px-2 h-10">
                        <button
                          type="button"
                          onClick={() => {
                            if (!mediaAllowed) {
                              openManager();
                              return;
                            }
                            actions.setVolume(volume === 0 ? lastNonZeroVolume : 0);
                          }}
                          disabled={!mediaAllowed}
                          aria-label={volume === 0 ? t("controls.unmute") : t("controls.mute")}
                          className={cn(
                            "h-8 w-8 flex items-center justify-center",
                            "disabled:opacity-50 disabled:cursor-not-allowed"
                          )}
                        >
                          {volume === 0 ? (
                            <VolumeX className="w-4 h-4 text-neo-text" />
                          ) : (
                            <Volume2 className="w-4 h-4 text-neo-text" />
                          )}
                        </button>
                        <input
                          type="range"
                          min={0}
                          max={100}
                          value={volume}
                          onChange={(e) => actions.setVolume(Number(e.target.value))}
                          disabled={!mediaAllowed}
                          aria-label={t("controls.volume")}
                          className={cn(
                            "w-24 accent-neo-accent",
                            "disabled:opacity-50 disabled:cursor-not-allowed"
                          )}
                        />
                      </div>

                      <a
                        href={externalUrl}
                        target="_blank"
                        rel="noopener noreferrer"
                        aria-label={t("controls.openOnSoundcloud")}
                        className={cn(
                          "hidden sm:inline-flex h-10 items-center gap-2 px-3 border-2 border-neo-border",
                          "bg-neo-bg text-neo-text shadow-[3px_3px_0px_0px_var(--neo-shadow)] hover:-translate-y-0.5 transition-transform"
                        )}
                      >
                        <ExternalLink className="w-4 h-4" />
                        <span className="hidden md:inline font-mono text-[10px] font-bold uppercase tracking-widest">
                          {t("controls.open")}
                        </span>
                      </a>

                      <button
                        type="button"
                        onClick={() => setIsCollapsed((prev) => !prev)}
                        aria-label={isCollapsed ? t("controls.expand") : t("controls.collapse")}
                        className={cn(
                          "h-9 w-9 sm:h-10 sm:w-10 border-2 border-neo-border bg-neo-bg text-neo-text shadow-[3px_3px_0px_0px_var(--neo-shadow)]",
                          "hover:-translate-y-0.5 transition-transform"
                        )}
                      >
                        {isCollapsed ? (
                          <ChevronUp className="w-5 h-5 mx-auto" />
                        ) : (
                          <ChevronDown className="w-5 h-5 mx-auto" />
                        )}
                      </button>

                      <button
                        type="button"
                        onClick={() => actions.dismiss()}
                        aria-label={t("controls.close")}
                        className={cn(
                          "h-9 w-9 sm:h-10 sm:w-10 border-2 border-neo-border bg-neo-text text-neo-text-inverse shadow-[3px_3px_0px_0px_var(--neo-shadow)]",
                          "hover:-translate-y-0.5 transition-transform"
                        )}
                      >
                        <X className="w-5 h-5 mx-auto" />
                      </button>

                      <a
                        href={externalUrl}
                        target="_blank"
                        rel="noopener noreferrer"
                        aria-label={t("controls.openOnSoundcloud")}
                        className={cn(
                          "sm:hidden h-9 w-9 sm:h-10 sm:w-10 border-2 border-neo-border bg-neo-bg text-neo-text shadow-[3px_3px_0px_0px_var(--neo-shadow)]",
                          "hover:-translate-y-0.5 transition-transform"
                        )}
                      >
                        <ExternalLink className="w-5 h-5 mx-auto mt-2.5" />
                      </a>
                    </div>
                  </div>

                  {/* Waveform + timing */}
                  <AnimatePresence initial={false}>
                    {!isCollapsed && (
                      <motion.div
                        key="waveform"
                        initial={{ height: 0, opacity: 0 }}
                        animate={{ height: "auto", opacity: 1 }}
                        exit={{ height: 0, opacity: 0 }}
                        transition={{ duration: 0.25, ease: "easeOut" }}
                        className="border-t-2 border-neo-border bg-neo-bg px-3 md:px-4 py-3 md:py-4 overflow-hidden"
                      >
                        <SoundCloudWaveform
                          samples={samples}
                          progress={progress}
                          disabled={controlsDisabled || durationMs <= 0}
                          onSeek={(ratio) => actions.seekToRatio(ratio)}
                          className={cn(isWaveformLoading && "opacity-80")}
                          height={38}
                        />
                        <div className="mt-2 flex items-center justify-between font-mono text-[10px] uppercase tracking-[0.18em] text-neo-text/60">
                          <span>{formatTime(positionMs)}</span>
                          <span>
                            -{formatTime(remainingMs)} / {formatTime(durationMs)}
                          </span>
                        </div>

                        {isPlayerUnavailable && (
                          <div className="mt-2 font-mono text-xs text-neo-text/70">
                            {t("status.errorHint")}
                          </div>
                        )}

                        <div className="mt-3 border-2 border-neo-border bg-neo-surface shadow-[4px_4px_0px_0px_var(--neo-shadow)] overflow-hidden">
                          <div className="px-3 py-2 border-b-2 border-neo-border bg-neo-text text-neo-text-inverse flex items-center justify-between">
                            <span className="font-mono text-[10px] uppercase tracking-[0.22em] text-white/70">
                              {t("tracklist.title")}
                            </span>
                            <span className="font-mono text-[10px] uppercase tracking-[0.22em] text-white/50">
                              {queue.length}
                            </span>
                          </div>
                          <SoundCloudTrackList
                            tracks={queue}
                            currentTrackId={track?.id ?? null}
                            currentIndex={currentIndex}
                            isPlaying={isPlaying}
                            isLoading={mediaAllowed && status === "loading"}
                            disabled={isPlayerUnavailable}
                            onSelect={(index) => {
                              if (!mediaAllowed) openManager();
                              actions.selectTrack(index);
                            }}
                            className="max-h-40 bg-neo-bg"
                          />
                        </div>
                      </motion.div>
                    )}
                  </AnimatePresence>
                </div>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {shouldShowReopen && (
          <motion.button
            type="button"
            initial={{ y: 20, opacity: 0, scale: 0.95 }}
            animate={{ y: 0, opacity: 1, scale: 1 }}
            exit={{ y: 20, opacity: 0, scale: 0.95 }}
            transition={{ duration: 0.25, ease: "easeOut" }}
            onClick={() => actions.open()}
            aria-label={t("controls.showPlayer")}
            className={cn(
              "fixed right-3 md:right-6 z-40",
              "h-14 w-14 border-4 border-neo-border bg-neo-accent text-neo-text-inverse",
              "shadow-[6px_6px_0px_0px_var(--neo-accent)] hover:-translate-y-0.5 transition-transform"
            )}
            style={{ bottom: `calc(${bottomOffsetPx}px + env(safe-area-inset-bottom))` }}
          >
            <SoundCloudIcon className="w-7 h-7 mx-auto" />
          </motion.button>
        )}
      </AnimatePresence>
    </>
  );
};

