export const fetchFullSoundCloudQueue = async (): Promise<boolean> => {
  if (hasFetchedFullQueue || isFetchingQueue) return hasFetchedFullQueue;

  isFetchingQueue = true;
  try {
    const res = await fetch("/api/soundcloud/tracks");
    if (!res.ok) {
