import { useMemo, useSyncExternalStore } from "react";

export const SOUND_CLOUD_PROFILE_URL = "https://soundcloud.com/loic-ghanem";
export const SOUND_CLOUD_TRACKS_URL = `${SOUND_CLOUD_PROFILE_URL}/tracks`;

