  artworkUrl?: string | null;
  waveformUrl?: string | null;
  permalinkUrl?: string | null;
  durationMs?: number;
  widgetIndex?: number;
};

export type GlobalAudioPlayerState = {
  status: GlobalAudioPlayerStatus;
  mediaAllowed: boolean;
  hasStarted: boolean;
  isDismissed: boolean;
  isPlaying: boolean;
  track: GlobalAudioTrack | null;
  queue: GlobalAudioTrack[];
  currentIndex: number | null;
  positionMs: number;
  durationMs: number;
  volume: number;
  error: string | null;
};

const VOLUME_STORAGE_KEY = "loic-player-volume-v1";

const DEFAULT_STATE: GlobalAudioPlayerState = {
  status: "idle",
  mediaAllowed: false,
  hasStarted: false,
  isDismissed: false,
  isPlaying: false,
  track: null,
  queue: [],
  currentIndex: null,
  positionMs: 0,
  durationMs: 0,
  volume: 80,
  error: null,
};

let state: GlobalAudioPlayerState = DEFAULT_STATE;
const listeners = new Set<() => void>();

const emit = () => {
  listeners.forEach((listener) => listener());
};

const setState = (
  partial:
    | Partial<GlobalAudioPlayerState>
    | ((prev: GlobalAudioPlayerState) => Partial<GlobalAudioPlayerState>)
) => {
  const patch = typeof partial === "function" ? partial(state) : partial;
  state = { ...state, ...patch };
  emit();
};

