  setGlobalAudioPlayerPlaying(true);
  if (getGlobalAudioPlayerState().queue.length === 0) refreshQueue();
  refreshSound();
});

widget.bind(events.PAUSE, () => {
  setGlobalAudioPlayerPlaying(false);
});

